import os
import tempfile
import struct
import subprocess
import sys

# Create a temporary file to act as our mock /dev/kvm
mock_kvm_path = "/tmp/mock_kvm"

try:
    # Create the mock device
    with open(mock_kvm_path, "w") as f:
        f.write("mock kvm device")

    print(f"Created mock KVM device at {mock_kvm_path}")

    # Set up LD_PRELOAD to intercept open calls
    preload_code = """
    #define _GNU_SOURCE
    #include <dlfcn.h>
    #include <string.h>
    #include <stdio.h>
    #include <fcntl.h>
    #include <unistd.h>
    #include <sys/ioctl.h>

    typedef int (*orig_open_t)(const char *pathname, int flags, ...);
    typedef int (*orig_ioctl_t)(int fd, unsigned long request, ...);

    // KVM ioctl constants
    #define KVM_GET_API_VERSION       0xAE00
    #define KVM_CREATE_VM            0xAE01
    #define KVM_SET_TSS_ADDR         0xAE14
    #define KVM_SET_USER_MEMORY_REGION 0x4020AE46
    #define KVM_CREATE_VCPU          0xAE41
    #define KVM_GET_VCPU_MMAP_SIZE   0xAE04
    #define KVM_RUN                  0xAE80
    #define KVM_GET_REGS             0x8090AE81
    #define KVM_SET_REGS             0x4090AE82
    #define KVM_GET_SREGS            0x8138AE83
    #define KVM_SET_SREGS            0x4138AE84

    #define KVM_EXIT_HLT             5

    int open(const char *pathname, int flags, ...) {
        orig_open_t orig_open = (orig_open_t)dlsym(RTLD_NEXT, "open");

        if (strcmp(pathname, "/dev/kvm") == 0) {
            printf("[HOOK] Intercepted open for /dev/kvm\\n");
            return orig_open("/tmp/mock_kvm", flags);
        }

        return orig_open(pathname, flags);
    }

    int ioctl(int fd, unsigned long request, ...) {
        void *arg;
        va_list ap;
        va_start(ap, request);
        arg = va_arg(ap, void *);
        va_end(ap);

        orig_ioctl_t orig_ioctl = (orig_ioctl_t)dlsym(RTLD_NEXT, "ioctl");

        printf("[HOOK] ioctl called with request 0x%lx\\n", request);

        // Handle different KVM ioctls
        switch (request) {
            case KVM_GET_API_VERSION:
                printf("[HOOK] KVM_GET_API_VERSION\\n");
                return 12; // Return KVM API version (current is 12)

            case KVM_CREATE_VM:
                printf("[HOOK] KVM_CREATE_VM\\n");
                return 3; // Return a fake VM fd

            case KVM_SET_TSS_ADDR:
                printf("[HOOK] KVM_SET_TSS_ADDR\\n");
                return 0;

            case KVM_SET_USER_MEMORY_REGION:
                printf("[HOOK] KVM_SET_USER_MEMORY_REGION\\n");
                return 0;

            case KVM_CREATE_VCPU:
                printf("[HOOK] KVM_CREATE_VCPU\\n");
                return 4; // Return a fake VCPU fd

            case KVM_GET_VCPU_MMAP_SIZE:
                printf("[HOOK] KVM_GET_VCPU_MMAP_SIZE\\n");
